declare(strict_types=1);require __DIR__.'/bootstrap.php';use Ogpn\Bot\{Bootstrap,Auth};$pdo=Bootstrap::pdo();$w=Auth::worker($pdo,'scan.claim');$body=json_decode(file_get_contents('php://input'),true)?:[];$limit=max(1,min(100,(int)($body['limit']??25)));$priority=(array)(require dirname(__DIR__).'/config/defaults.php')['queue']['priority_tlds'];$pdo->beginTransaction();$order="CASE WHEN tld IN ('".implode("','",array_map(fn($x)=>preg_replace('/[^a-z0-9-]/','',$x),$priority))."') THEN 0 ELSE 1 END, CASE WHEN last_scanned_at IS NULL THEN 0 ELSE 1 END, COALESCE(next_scan_at,'1970-01-01'), COALESCE(last_scanned_at,'1970-01-01')";$s=$pdo->query("SELECT id,domain FROM domain_queue WHERE (reserved_until IS NULL OR reserved_until<UTC_TIMESTAMP()) AND (last_scanned_at IS NULL OR next_scan_at<=UTC_TIMESTAMP()) ORDER BY $order LIMIT $limit FOR UPDATE");$rows=$s->fetchAll();if($rows){$ids=implode(',',array_map('intval',array_column($rows,'id')));$pdo->exec("UPDATE domain_queue SET reserved_by=".$pdo->quote($w['worker_id']).",reserved_until=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 20 MINUTE) WHERE id IN ($ids)");}$pdo->commit();Bootstrap::json(['domains'=>array_column($rows,'domain')]);
